#[test]
fn max_message_bytes_limits_body_in_bytes() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 4}}));
    let send = |body: &str| json!({"Command": "SendMessage", "QueueName": "q", "Body": body});
    h.ok(send("abcd"));
    assert_eq!(h.err(send("abcde")), "InvalidParameterValue");
    // two characters, four bytes
    h.ok(send("éé"));
    assert_eq!(h.err(send("ééé")), "InvalidParameterValue");
}

#[test]
fn max_message_bytes_wins_over_unsupported_operation() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 1}}));
    let command = json!({"Command": "SendMessage", "QueueName": "q", "Body": "ab", "GroupId": "g"});
    assert_eq!(h.err(command), "InvalidParameterValue");
}

#[test]
fn lowering_max_message_bytes_keeps_existing_messages() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    h.ok(json!({"Command": "SendMessage", "QueueName": "q", "Body": "long body"}));
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"MaxMessageBytes": 2}}));
    let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    assert_eq!(r["Messages"][0]["Body"], "long body");
    let attrs = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert_eq!(attrs["Attributes"]["MaxMessageBytes"], 2);
}

#[test]
fn max_message_bytes_range_and_create_rule_4() {
    let mut h = Harness::new();
    for bad in [json!(0), json!(1025), json!("5")] {
        let c = json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": bad}});
        assert_eq!(h.err(c), "InvalidParameterValue");
    }
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 10}}));
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 10}}));
    assert_eq!(
        h.err(json!({"Command": "CreateQueue", "QueueName": "q"})),
        "QueueAlreadyExists"
    );
}
